// Props-only Jolt world for Wheelie King's custom motorcycle engines.
// Jolt has NO bike or vehicle constraint here. It simulates loose crates/barrels,
// rigid-body collisions, gravity and a heightfield generated by V3 terrain.
import initJolt from './vendor/jolt/jolt-physics.wasm.js';
const STATIC=0,DYNAMIC=1;
export function createV3JoltProps(T,scene,terrain){
  const api={ready:false,error:null,count:0,region:null};
  let J=null,world=null,iface=null,physics=null,floor=null,disposed=false;
  const objects=[],meshes=[],geometries=[],materials=[];
  const root=new T.Group();root.name='wk:v3-jolt-props';scene.add(root);
  const boxMat=new T.MeshStandardMaterial({color:'#92715a',roughness:.85}),barrelMat=new T.MeshStandardMaterial({color:'#b25f35',metalness:.2,roughness:.6});
  materials.push(boxMat,barrelMat);
  const quad=[0,0,0,1];
  const removeBody=body=>{if(!body||!iface)return;const id=body.GetID();try{iface.RemoveBody(id);}catch{}try{iface.DestroyBody(id);}catch{}};
  function addBody(shape,x,y,z,motion,mass=1){
    const data=new J.BodyCreationSettings(shape,new J.RVec3(x,y,z),new J.Quat(...quad),
      motion===STATIC?J.EMotionType_Static:J.EMotionType_Dynamic,motion);
    data.mFriction=.8;data.mRestitution=.15;
    if(motion===DYNAMIC){data.mOverrideMassProperties=J.EOverrideMassProperties_CalculateInertia;data.mMassPropertiesOverride.mMass=mass;}
    const body=iface.CreateBody(data);
    iface.AddBody(body.GetID(),motion===STATIC?J.EActivation_DontActivate:J.EActivation_Activate);
    J.destroy(data);return body;
  }
  function clear(){
    for(const obj of objects)removeBody(obj.body);objects.length=0;
    for(const mesh of meshes){root.remove(mesh);mesh.geometry.dispose();}meshes.length=0;
    removeBody(floor);floor=null;
  }
  function generateRegion(cx,cz){
    if(!api.ready||disposed)return;
    clear();
    // One streamed 144m square terrain heightfield; regenerate when rider
    // travels far enough that old bodies cannot fall off the collision region.
    const N=65,CELL=2.25,originX=cx-(N-1)*CELL/2,originZ=cz-(N-1)*CELL/2;
    const hs=new J.HeightFieldShapeSettings();
    hs.mOffset=new J.Vec3(0,0,0);hs.mScale=new J.Vec3(CELL,1,CELL);
    hs.mSampleCount=N;hs.mBlockSize=4;
    hs.mHeightSamples.reserve(N*N);
    for(let j=0;j<N;j++)for(let i=0;i<N;i++)hs.mHeightSamples.push_back(terrain.height(originX+i*CELL,originZ+j*CELL));
    const res=hs.Create();
    if(res.HasError())throw new Error('V3 prop heightfield: '+res.GetError().c_str());
    floor=addBody(res.Get(),originX,0,originZ,STATIC);
    J.destroy(hs);
    for(let i=0;i<14;i++){
      const angle=i*2.3999632297,r=7+3*(i%4),x=cx+Math.cos(angle)*r,z=cz+Math.sin(angle)*r;
      if(Math.abs(z-(terrain.trailZ?.(x)??0))<3&&i%2)continue;
      const isBox=i%3!==0,scale=.45+(i%4)*.12,y=terrain.height(x,z)+2+(i%3)*.35;
      const shape=isBox?new J.BoxShape(new J.Vec3(scale,scale,scale)):new J.SphereShape(scale);
      const body=addBody(shape,x,y,z,DYNAMIC,isBox?9+2*i:6+i);
      const geo=isBox?new T.BoxGeometry(scale*2,scale*2,scale*2):new T.SphereGeometry(scale,12,8);
      const mesh=new T.Mesh(geo,isBox?boxMat:barrelMat);mesh.castShadow=true;mesh.receiveShadow=true;
      root.add(mesh);objects.push({body,mesh,radius:scale,hitAt:0});meshes.push(mesh);
    }
    api.region={x:cx,z:cz,size:(N-1)*CELL};api.count=objects.length;
  }
  async function start(x=-600,z=0){
    if(api.ready||disposed)return api;
    try{
      J=await initJolt();if(disposed)return api;
      const settings=new J.JoltSettings();
      const pairs=new J.ObjectLayerPairFilterTable(2);
      pairs.EnableCollision(STATIC,DYNAMIC);pairs.EnableCollision(DYNAMIC,DYNAMIC);
      const bp=new J.BroadPhaseLayerInterfaceTable(2,2);
      bp.MapObjectToBroadPhaseLayer(STATIC,new J.BroadPhaseLayer(0));
      bp.MapObjectToBroadPhaseLayer(DYNAMIC,new J.BroadPhaseLayer(1));
      settings.mObjectLayerPairFilter=pairs;settings.mBroadPhaseLayerInterface=bp;
      settings.mObjectVsBroadPhaseLayerFilter=new J.ObjectVsBroadPhaseLayerFilterTable(bp,2,pairs,2);
      world=new J.JoltInterface(settings);J.destroy(settings);
      physics=world.GetPhysicsSystem();iface=physics.GetBodyInterface();api.ready=true;
      generateRegion(x,z);
    }catch(e){api.error=e?.message||String(e);api.ready=false;console.warn('[wk] optional V3 Jolt props unavailable',e);}
    return api;
  }
  let time=0;
  function step(dt,bike){
    if(!api.ready||disposed)return;
    const x=bike?.x??api.region?.x??0,z=bike?.z??api.region?.z??0;
    if(api.region&&Math.hypot(x-api.region.x,z-api.region.z)>55)generateRegion(x,z);
    dt=Math.max(0,Math.min(.05,dt));if(!dt)return;
    time+=dt;
    if(bike&&!bike.crashed){
      for(const o of objects){
        const q=o.body.GetPosition(),dx=q.GetX()-x,dy=q.GetY()-(bike.y||0),dz=q.GetZ()-z;
        const rr=o.radius+.65,dist=Math.hypot(dx,dz);
        if(dist<rr&&Math.abs(dy)<1.2&&time-o.hitAt>.14){
          const dir=dist>.05?{x:dx/dist,z:dz/dist}:{x:Math.cos(bike.yaw||0),z:Math.sin(bike.yaw||0)};
          const force=3+Math.min(18,Math.abs(bike.vx||0)*1.4);
          try{iface.AddImpulse(o.body.GetID(),new J.Vec3(dir.x*force,Math.max(1,force*.25),dir.z*force));}catch(e){api.error=e.message;}
          // One-way impulse bridge: Jolt moves the prop, our bike receives a
          // bounded recoil. Two solvers never integrate the same rigid body.
          if(Number.isFinite(bike.wx)){bike.wx-=dir.x*force/Math.max(35,bike.mass||100)*.32;bike.wz-=dir.z*force/Math.max(35,bike.mass||100)*.32;}
          o.hitAt=time;
        }
      }
    }
    world.Step(dt,Math.max(1,Math.ceil(dt*120)));
    for(const o of objects){
      const p=o.body.GetPosition(),q=o.body.GetRotation();
      o.mesh.position.set(p.GetX(),p.GetY(),p.GetZ());
      o.mesh.quaternion.set(q.GetX(),q.GetY(),q.GetZ(),q.GetW());
    }
  }
  function dispose(){disposed=true;api.ready=false;clear();try{world?.Destroy?.();}catch{}world=null;iface=null;physics=null;J=null;
    for(const m of materials)m.dispose();root.removeFromParent();}
  return {api,start,step,dispose,snapshot:()=>({...api})};
}
